INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('1082181f-d979-4672-b6c4-34533e25c98d', 'ar', $aimseed$تعليمات الفصل الدراسي$aimseed$, $aimseed$استمع إلى أوامر الفصل الدراسي الشائعة وتجاوب معها.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستسمع أوامر شائعة في الفصل الدراسي وتتعلّم كيف تجيب عنها. معرفة هذه العبارات تساعدك على اتباع التعليمات في أي صف. بعد الدرس ستفهم الأوامر وتستطيع الرد عليها بشكل صحيح.","sections":[{"heading":"أوامر الفصل الشائعة","body":"- استمع جيدًا إلى المعلم.\n- تعرّف على الكلمة الأساسية.\n- تذكّر الجواب القصير المطلوب.","examples":[{"text":"Sit down, please.","note":"أمر بالجلوس"},{"text":"Open your book to page 10.","note":"أمر بفتح صفحة معينة"},{"text":"Raise your hand if you have a question.","note":"أمر لإظهار رغبتك في الكلام"},{"text":"Close the door quietly.","note":"أمر بإغلاق الباب"}]},{"heading":"كيف تجيب","body":"- استخدم جوابًا قصيرًا ومهذّبًا.\n- اجعل ردّك بسيطًا.\n- أظهر أنك فهمت.","examples":[{"text":"Okay, I will sit down.","note":"ردّ إيجابي"},{"text":"Sure, I am opening it now.","note":"ردّ إيجابي"},{"text":"Yes, I have raised my hand.","note":"ردّ إيجابي"},{"text":"Sorry, I will close it now.","note":"اعتذار ثم تنفيذ"}]},{"heading":"تدرّب على الاستماع والإجابة","body":"- استمع إلى المقطع الصوتي مرة واحدة.\n- توقّف وكرّر الأمر.\n- قل الجواب الصحيح بصوت عالٍ.\n- تحقّق من أن جوابك يطابق النموذج.","examples":[{"text":"Listen: \"Listen to the teacher.\"","note":"تدرّب على سماع الأمر"},{"text":"Respond: \"I am listening.\"","note":"جواب قصير صحيح"},{"text":"Listen: \"Write your name on the paper.\"","note":"تدرّب على سماع أمر آخر"},{"text":"Respond: \"I have written it.\"","note":"جواب قصير صحيح"}]}],"keyPoints":["انتبه للفعل الرئيسي في الأمر","أجب بعبارة قصيرة ومهذّبة","استخدم \"I will\" للأفعال التي ستفعلها الآن","استخدم \"I have\" للأفعال التي أنجزتها بالفعل"],"commonMistakes":[{"wrong":"Sit down now!","right":"Okay, I will sit down.","why":"أضف جوابًا مهذّبًا ولا تكتفِ بتكرار الأمر"},{"wrong":"Open book page ten","right":"Sure, I am opening it now.","why":"استخدم جملة كاملة فيها فعل"},{"wrong":"Raise hand?","right":"Yes, I have raised my hand.","why":"أجب بالإيجاب ولا تجب بسؤال"},{"wrong":"Close door quiet","right":"Sorry, I will close it now.","why":"أضف كلمة مهذّبة واستخدم صيغة الفعل الصحيحة"}],"recap":"استمع إلى كل أمر، وتوقّف، ثم تدرّب على قول الجواب القصير. واصل التدريب حتى تصبح الإجابات طبيعية عندك."},"assets":{"5fa1cb3e-21c1-422e-bd33-a40704e4291f":{"title":"استمع: أوامر الفصل","description":"استمع إلى كل أمر."}}}$aimseed$::jsonb)
