-- lesson 1a63d1ef-9f4a-4ea5-bc73-ca503b3a7825: My Name Is...
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('1a63d1ef-9f4a-4ea5-bc73-ca503b3a7825', 'ar', $aimseed$My Name Is...$aimseed$, $aimseed$تعلّم كيف تعرّف بنفسك وتسأل عن اسم شخص آخر.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستتعلّم كيف تقول اسمك وكيف تسأل شخصًا آخر عن اسمه. هذه الجمل نستخدمها كل يوم عندما نقابل أشخاصًا جددًا. بعد الدرس ستتمكّن من التعريف بنفسك وسؤال شخص عن اسمه بأدب.","sections":[{"heading":"قل اسمك","body":"- استخدم **My name is …**\n- ويمكنك أيضًا قول **I am …**\n- اجعل الجملة قصيرة وواضحة","examples":[{"text":"My name is Ahmed","note":"النمط الأساسي مع ‘My name is’"},{"text":"I am Ahmed","note":"بديل له المعنى نفسه"}]},{"heading":"اسأل عن اسم الآخر","body":"- استخدم **What is your name?**\n- والصيغة الأقصر هي **What’s your name?**\n- قلها بنبرة ودّية","examples":[{"text":"What is your name?","note":"السؤال المعتاد"},{"text":"What’s your name?","note":"الصيغة المختصرة الشائعة"}]},{"heading":"أجب بأدب","body":"- بعد أن تسمع الاسم، قل **Nice to meet you**\n- يمكنك تكرار الاسم لتُظهر أنك أصغيت\n- واختم بابتسامة","examples":[{"text":"Nice to meet you, Ahmed","note":"ردّ مهذّب بعد سماع الاسم"},{"text":"My name is Sara. And you?","note":"عرّف بنفسك ثم اسأل الطرف الآخر"}]}],"keyPoints":["استخدم ‘My name is …’ أو ‘I am …’ لذكر اسمك","اسأل ‘What is your name?’ لتعرف اسم الآخر","أضف ‘Nice to meet you’ بعد سماع الاسم","اجعل جملك قصيرة وواضحة"],"commonMistakes":[{"wrong":"My name Ahmed","right":"My name is Ahmed","why":"الفعل ‘is’ يربط الاسم بكلمة ‘my name’"},{"wrong":"You name?","right":"What is your name?","why":"الأسئلة في الإنجليزية تحتاج إلى أداة استفهام"},{"wrong":"I name is Ahmed","right":"My name is Ahmed","why":"استخدم ضمير الملكية ‘my’ وليس ‘I’"}],"recap":"تدرّب الآن مع زميل على قول اسمك وسؤال الآخرين عن أسمائهم."},"assets":{"811f1435-fced-41bf-9be0-caa95d33651f":{"title":"التعريف بنفسك","description":"My name is Sara. (اسمي سارة.) I am Sara. (أنا سارة.) What is your name? (ما اسمك؟)"}}}$aimseed$::jsonb)
ON CONFLICT (lesson_id, locale) DO UPDATE SET content = EXCLUDED.content;
