-- lesson 1fead9f5-0622-4340-b535-1c058c524373: Short Vowel Sounds
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('1fead9f5-0622-4340-b535-1c058c524373', 'ar', $aimseed$أصوات حروف العلة القصيرة$aimseed$, $aimseed$تدرّب على أصوات حروف العلة الخمسة القصيرة: a وe وi وo وu.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستتعلم أصوات حروف العلة القصيرة الخمسة a وe وi وo وu. تظهر هذه الأصوات في كثير من الكلمات اليومية، ومعرفتها تساعدك على القراءة والكلام بوضوح. وبعد الدرس ستستطيع نطق هذه الأصوات والتعرّف عليها في الكلمات البسيطة.","sections":[{"heading":"ما هي حروف العلة القصيرة","body":"- حروف العلة القصيرة هي الأصوات السريعة في كلمات مثل cat وbed.\n- وهي تختلف عن الأصوات الطويلة التي تسمعها في name وsee.\n- في الإنجليزية خمسة أصوات قصيرة لحروف العلة: a وe وi وo وu.","examples":[{"text":"cat (short a)","note":"يوضح صوت a القصير"},{"text":"bed (short e)","note":"يوضح صوت e القصير"}]},{"heading":"كيف تنطق كل صوت","body":"- **a**: افتح فمك قليلًا واجعل اللسان منخفضًا، وانطق /æ/ كما في cat.\n- **e**: ابتسم ابتسامة خفيفة واجعل اللسان في الوسط، وانطق /e/ كما في bed.\n- **i**: أبقِ فمك مرتخيًا واجعل اللسان مرتفعًا، وانطق /ɪ/ كما في sit.\n- **o**: دوّر شفتيك قليلًا واجعل اللسان منخفضًا، وانطق /ɒ/ كما في hot.\n- **u**: أرخِ شفتيك واجعل اللسان منخفضًا، وانطق /ʌ/ كما في cup.","examples":[{"text":"sit (short i)","note":"يوضح صوت i القصير"},{"text":"hot (short o)","note":"يوضح صوت o القصير"}]},{"heading":"تدرّب بكلمات بسيطة","body":"- اقرأ كل كلمة ببطء وكرّر صوت حرف العلة.\n- استخدم الكلمات في جمل قصيرة لتسمع الصوت في سياقه.\n- استمع إلى صديق ينطق الكلمات وحاول تقليده بدقة.","examples":[{"text":"The cat is on the mat.","note":"صوت a القصير في cat وmat"},{"text":"I have a cup of tea.","note":"صوت u القصير في cup"}]}],"keyPoints":["هناك خمسة أصوات قصيرة فقط لحروف العلة: a وe وi وo وu.","صوت a القصير يشبه الصوت في cat، وليس الصوت في name.","صوت e القصير يشبه الصوت في bed، وليس الصوت في see.","صوت i القصير يشبه الصوت في sit، وليس الصوت في kite.","صوت o القصير يشبه الصوت في hot، وليس الصوت في home.","صوت u القصير يشبه الصوت في cup، وليس الصوت في music."],"commonMistakes":[{"wrong":"Saying a long vowel like /eɪ/ in cat","right":"Say the short /æ/ sound","why":"كثيرًا ما يمدّ المتحدثون بالعربية حرف العلة"},{"wrong":"Adding an extra vowel after the short sound, e.g., ‘caaat’","right":"Keep the sound brief and stop after one beat","why":"حروف العلة القصيرة سريعة"},{"wrong":"Pronouncing i as /iː/ like in machine","right":"Use the short /ɪ/ as in sit","why":"صوت i القصير أخفض وأقصر"},{"wrong":"Rounding lips too much for short o","right":"Make a small round shape, not a big one","why":"المبالغة في تدوير الشفتين تحوّل الصوت إلى o طويل"}],"recap":"تدرّب على نطق أصوات حروف العلة القصيرة الخمسة في الكلمات المذكورة، ثم حاول استخدامها في جمل بسيطة من عندك."},"assets":{"cb8e281a-3da1-441b-b300-8c16be9252c5":{"title":"كلمات حروف العلة القصيرة","description":"cat (a), bed (e), sit (i), hot (o), cup (u)."}}}$aimseed$::jsonb)
