-- lesson 22401737-36b8-445e-a899-98a446d735c1: Meeting Someone New
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('22401737-36b8-445e-a899-98a446d735c1', 'ar', $aimseed$التعرّف على شخص جديد$aimseed$, $aimseed$استمع إلى حوار قصير بين شخصين يلتقيان للمرة الأولى.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستسمع محادثة قصيرة بين شخصين يلتقيان للمرة الأولى. ستتعلّم أشهر عبارات التحية، وكيف تسأل عن الاسم وتذكر اسمك، وكيف تودّع. بعد الاستماع ستتمكّن من متابعة حوار تعارف بسيط.","sections":[{"heading":"التحيات","body":"- Hello\n- Hi\n- Good morning\n- Good afternoon","examples":[{"text":"Hello, my name is Anna.","note":"تحية شائعة يتبعها اسم"},{"text":"Hi, I am Ahmed.","note":"تحية بسيطة أخرى مع اسم"}]},{"heading":"السؤال عن الاسم وذكره","body":"- What is your name?\n- My name is ...\n- I am ...","examples":[{"text":"What is your name?","note":"سؤال لمعرفة اسم شخص"},{"text":"My name is Sam.","note":"جواب يذكر اسمك"},{"text":"I am Fatima.","note":"طريقة أخرى لذكر اسمك"}]},{"heading":"عبارات الوداع","body":"- Nice to meet you\n- Goodbye\n- See you later","examples":[{"text":"Nice to meet you.","note":"عبارة مهذّبة بعد التعارف"},{"text":"Goodbye!","note":"طريقة بسيطة لإنهاء المحادثة"},{"text":"See you later.","note":"وداع غير رسمي"}]},{"heading":"نصائح للاستماع","body":"- انتبه للكلمات: Hello, Hi, What is your name?, My name is, Goodbye.\n- انتبه لنبرة المتحدث؛ النبرة الودّية تدل على التحية.\n- عُدّ الجمل القصيرة؛ معظم حوارات التعارف لها ثلاثة أجزاء: التحية، وتبادل الأسماء، والوداع.","examples":[{"text":"Hello, my name is Anna. What is your name? My name is Ahmed. Nice to meet you. Goodbye!","note":"البنية المعتادة لحوار تعارف قصير"}]}],"keyPoints":["استخدم Hello أو Hi لبدء المحادثة","اسأل What is your name? لتعرف اسم الشخص الآخر","أجب بـ My name is … أو I am …","اختم بـ Nice to meet you أو Goodbye","انتبه للأجزاء الثلاثة: التحية، وتبادل الأسماء، والوداع"],"commonMistakes":[{"wrong":"Your name?","right":"What is your name?","why":"في العربية قد نحذف أداة الاستفهام، أما الإنجليزية فتحتاج إلى السؤال كاملًا"},{"wrong":"Name is Ahmed","right":"My name is Ahmed","why":"الضمير My ضروري لتبدو الجملة طبيعية"},{"wrong":"Bye bye","right":"Goodbye","why":"Bye bye غير رسمية وقد تبدو طفولية في أول لقاء"},{"wrong":"Hello good morning","right":"Good morning","why":"استخدم تحية واحدة فقط في كل مرة"}],"recap":"استمع إلى الحوار مرة أخرى، وكرّر كل جملة، وحاول أن تقول بنفسك التحيات وأسئلة الاسم وعبارات الوداع."},"assets":{"854d955e-b3b1-4b19-a75b-0497c67eca36":{"title":"استمع: شخصان يلتقيان","description":"محادثة قصيرة بين صديقين جديدين."}}}$aimseed$::jsonb)
