-- lesson 45256e4f-559f-4d32-8652-53d61dc2e241: Hello & Goodbye
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('45256e4f-559f-4d32-8652-53d61dc2e241', 'ar', $aimseed$مرحبًا ووداعًا$aimseed$, $aimseed$تعلّم أكثر عبارات التحية والوداع شيوعًا.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستتعلّم أشهر طرق قول مرحبًا ووداعًا. وستتعلّم أيضًا كيف تحيّي الناس في أوقات مختلفة من اليوم وكيف تعرّف بنفسك باسمك. بعد الدرس ستتمكّن من تحيّة الغرباء وقول وداعًا بإنجليزية بسيطة.","sections":[{"heading":"التحيات البسيطة","body":"- استخدم كلمات قصيرة لبدء المحادثة.\n- \"Hello\" تصلح في أي وقت من اليوم.\n- \"Hi\" غير رسمية وودّية.\n- \"Hey\" عفوية جدًا مع الأصدقاء.","examples":[{"text":"Hello!","note":"تحية أساسية تقولها لأي شخص"},{"text":"Hi, how are you?","note":"تحية غير رسمية مع سؤال"},{"text":"Hey! Nice to see you.","note":"تحية عفوية جدًا"}]},{"heading":"تحيات حسب وقت اليوم","body":"- اختر التحية المناسبة للوقت.\n- \"Good morning\" تُستخدم حتى الساعة 12 ظهرًا تقريبًا.\n- \"Good afternoon\" من الساعة 12 ظهرًا حتى 6 مساءً تقريبًا.\n- \"Good evening\" بعد الساعة 6 مساءً.\n- ويمكنك دائمًا قول \"Hello\" في أي وقت.","examples":[{"text":"Good morning, Sara.","note":"تحية الصباح"},{"text":"Good afternoon, Mr. Ahmed.","note":"تحية بعد الظهر"},{"text":"Good evening, everyone.","note":"تحية المساء"}]},{"heading":"قول وداعًا","body":"- استخدم كلمات قصيرة لإنهاء المحادثة.\n- \"Goodbye\" مهذّبة وتصلح في أي وقت.\n- \"Bye\" غير رسمية وشائعة.\n- يمكنك إضافة \"see you later\" لنبرة ودّية.","examples":[{"text":"Goodbye! See you tomorrow.","note":"وداع مهذّب"},{"text":"Bye! Take care.","note":"وداع غير رسمي"},{"text":"See you later!","note":"طريقة ودّية لقول وداعًا"}]},{"heading":"التعريف بنفسك","body":"- اذكر اسمك بعد التحية.\n- استخدم \"I am\" أو \"My name is\".\n- اجعل جملتك قصيرة وواضحة.\n- يمكنك إضافة عبارة لطيفة مثل \"nice to meet you\".\n- مثال: \"Hello, I am Ali.\"","examples":[{"text":"Hello, I am Ali.","note":"تعريف بسيط بنفسك"},{"text":"Hi, my name is Fatima.","note":"طريقة أخرى للتعريف بنفسك"},{"text":"Good morning, I am Omar. Nice to meet you.","note":"تضيف عبارة مهذّبة"}]}],"keyPoints":["Hello وHi تحيتان يوميتان","Good morning/afternoon/evening تناسب وقت اليوم","Goodbye مهذّبة، أما Bye فغير رسمية","استخدم I am أو My name is لذكر اسمك","أضف Nice to meet you بعد اسمك للمجاملة"],"commonMistakes":[{"wrong":"Hello night!","right":"Good evening!","why":"استخدم \"Good evening\" عند حلول الليل"},{"wrong":"Bye bye you!","right":"Bye! See you later!","why":"تجنّب الكلمات الزائدة التي تبدو غير طبيعية"},{"wrong":"I name is Ali.","right":"My name is Ali.","why":"العبارة الصحيحة هي \"My name is\""},{"wrong":"Good morning, I am night.","right":"Good morning, I am Ahmed.","why":"لا تخلط تحية الوقت مع اسم غير صحيح"}],"recap":"تدرّب على تحية الناس وقول وداعًا والتعريف بنفسك باسمك في محادثات قصيرة."},"assets":{"649ab678-41bf-46b4-9c7f-6554816529f3":{"title":"عبارات التحية","description":"Hello! (مرحبًا) Hi! (أهلًا) Good morning. (صباح الخير) Good afternoon. (مساء الخير بعد الظهر) Good evening. (مساء الخير) Goodbye. (مع السلامة) Bye! (وداعًا)"}}}$aimseed$::jsonb)
