-- lesson 6d2c142e-2e0a-4561-901d-78696258ef79: Everyday Survival Phrases
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('6d2c142e-2e0a-4561-901d-78696258ef79', 'ar', $aimseed$عبارات البقاء اليومية$aimseed$, $aimseed$تعلّم العبارات الأساسية: please, thank you, sorry, excuse me, yes, no.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستتعلّم كلمات مهذّبة وقصيرة تساعدك في المواقف اليومية. ستتمكّن من طلب المساعدة، وشكر الناس، والاعتذار، والإجابة عن أسئلة بسيطة بالإنجليزية.","sections":[{"heading":"الطلبات المهذّبة","body":"- استخدم **please** عندما تريد شيئًا.\n- قل **thank you** بعد أن يساعدك أحد.\n- كلتا الكلمتين تجعلانك تبدو ودودًا.","examples":[{"text":"Can you pass the salt, please?","note":"توضّح الطلب باستخدام please"},{"text":"Thank you for your help.","note":"تعبّر عن الامتنان"}]},{"heading":"الاعتذار ولفت الانتباه","body":"- قل **sorry** عندما ترتكب خطأً.\n- استخدم **excuse me** للفت انتباه شخص أو للمرور.\n- كلتاهما مفيدتان في الأماكن المزدحمة.","examples":[{"text":"Sorry, I am late.","note":"اعتذار بسيط"},{"text":"Excuse me, where is the bathroom?","note":"طلب المساعدة بأدب"}]},{"heading":"إجابات بسيطة وطلب التوضيح","body":"- **Yes** و**no** تجيبان عن الأسئلة مباشرة.\n- قل **I don’t understand** عندما تحتاج إلى مزيد من الشرح.\n- اجعل جملك قصيرة وواضحة.","examples":[{"text":"Do you speak English? Yes.","note":"إجابة بالإيجاب"},{"text":"Do you need water? No.","note":"إجابة بالنفي"},{"text":"I don’t understand the question.","note":"طلب التوضيح"}]}],"keyPoints":["Please تضيف الأدب إلى الطلبات","Thank you تعبّر عن التقدير","Sorry للاعتذار عن خطأ","Excuse me للفت الانتباه أو لطلب المرور","Yes وno إجابتان واضحتان","I don’t understand لطلب المساعدة"],"commonMistakes":[{"wrong":"Please thank you","right":"Thank you, please","why":"اعكس الترتيب؛ thank you تأتي أولًا"},{"wrong":"Excuse me I am sorry","right":"Sorry, excuse me","why":"استخدم عبارة واحدة في كل مرة ليكون الكلام واضحًا"},{"wrong":"Yes I no","right":"Yes or No","why":"لا تجمع بين إجابتين متعاكستين"}],"recap":"تدرّب على هذه العبارات الست في محادثات حقيقية حتى تصبح طبيعية عندك."},"assets":{"b2b463d0-a595-4bbf-9b0b-5232cf7594a7":{"title":"عبارات البقاء","description":"Please. (من فضلك) Thank you. (شكرًا) Sorry. (آسف) Excuse me. (عفوًا) Yes. (نعم) No. (لا) I don't understand. (لا أفهم.)"}}}$aimseed$::jsonb)
