-- lesson 8e45a282-d726-48ef-97c5-897764156bb9: Numbers 11-20
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('8e45a282-d726-48ef-97c5-897764156bb9', 'ar', $aimseed$الأرقام من 11 إلى 20$aimseed$, $aimseed$تعلّم نطق الأرقام من 11 إلى 20 والتعرّف عليها.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستتعلم الكلمات الإنجليزية للأرقام من أحد عشر إلى عشرين. معرفة هذه الأرقام تتيح لك أن تتحدث عن العمر والمال والتواريخ وكثير من مواقف الحياة اليومية. وبعد الدرس ستستطيع نطق الأرقام من 11 إلى 20 والتعرّف عليها وكتابتها بشكل صحيح.","sections":[{"heading":"كلمات الأرقام من 11 إلى 20","body":"- eleven\n- twelve\n- thirteen\n- fourteen\n- fifteen\n- sixteen\n- seventeen\n- eighteen\n- nineteen\n- twenty","examples":[{"text":"I have eleven apples.","note":"يوضح كلمة eleven"},{"text":"She bought twelve cookies.","note":"يوضح كلمة twelve"},{"text":"We saw thirteen birds.","note":"يوضح كلمة thirteen"},{"text":"He is fourteen years old.","note":"يوضح كلمة fourteen"}]},{"heading":"كيف تنطقها","body":"- صوت **th** في thirteen ناعم، كما في *think*: ضع طرف اللسان بين الأسنان وأخرج الهواء بلطف.\n- انتبه إلى النبر: في eleven يقع على المقطع الثاني، وفي thirteen وfourteen وبقية كلمات -teen يقع على -teen عند نطقها وحدها.\n- انطق الكلمة كاملة، لا الرقم مع \"ten\" (مثلًا قل *eleven* وليس *one ten*).","examples":[{"text":"eleven","note":"الكلمة كاملة بدل \"one ten\""},{"text":"thirteen","note":"صوت th الناعم"},{"text":"seventeen","note":"موضع النبر في الكلمة"}]},{"heading":"استخدام الأرقام في الجمل","body":"- ضع كلمة الرقم قبل الاسم.\n- استخدم صيغة الجمع للاسم عندما يكون الرقم أكبر من واحد.\n- يمكنك أيضًا استخدام الرقم للتعبير عن العمر أو التاريخ.","examples":[{"text":"My brother is fifteen years old.","note":"الرقم قبل الاسم \"years\""},{"text":"They have sixteen chairs.","note":"الاسم بصيغة الجمع بعد الرقم"},{"text":"The meeting starts at eighteen o'clock.","note":"استخدام الرقم للتعبير عن الوقت"}]},{"heading":"كتابة الأرقام","body":"- اكتب الرقم بالأرقام (digits) كلما أمكن.\n- الرقم المكتوب يطابق الكلمة المنطوقة.\n- تدرّب على مطابقة الكلمة بالرقم.","examples":[{"text":"20 = twenty","note":"يوضح رقم twenty"},{"text":"13 = thirteen","note":"يوضح رقم thirteen"}]}],"keyPoints":["eleven إلى twenty كلمات مفردة، وليست مثل \"ten‑one\" وغيرها","صوت \"th\" في thirteen ناعم، كما في think","انتبه إلى النبر: في eleven يقع على المقطع الثاني، وفي thirteen وما يشبهها يقع على -teen عند نطقها وحدها","ضع كلمة الرقم قبل الاسم","الرقم 13 يطابق كلمة thirteen"],"commonMistakes":[{"wrong":"one ten","right":"eleven","why":"كثيرًا ما يترجم المتحدثون بالعربية نمط 10 + 1"},{"wrong":"twenty‑one for 20","right":"twenty","why":"كلمة twenty تقف وحدها، وهي ليست twenty‑one"},{"wrong":"saying \"fifteenth\" for 15","right":"fifteen","why":"صيغة الترتيب (fifteenth) تختلف عن صيغة العدد (fifteen)"}],"recap":"تدرّب على نطق الأرقام من eleven إلى twenty والاستماع إليها وكتابتها حتى تصبح مألوفة لديك."},"assets":{"b1ca9c85-ac6d-48cf-876d-1ab7f8ab3201":{"title":"الأرقام من 11 إلى 20","description":"eleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty"}}}$aimseed$::jsonb)
