-- lesson 91ed04f5-2451-4a5e-ba87-8019a26cf5db: Consonant Pairs & Blends
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('91ed04f5-2451-4a5e-ba87-8019a26cf5db', 'ar', $aimseed$أزواج الحروف الساكنة والمقاطع المركّبة$aimseed$, $aimseed$استمع إلى أصوات الحروف الساكنة الصعبة مثل p/b وf/v والمقاطع المركّبة مثل "bl" و"st" وتدرّب عليها.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستسمع الفروق الدقيقة بين صوتي p وb، وصوتي f وv، وتتعلم كيف تنطق المقاطع المركّبة البسيطة مثل bl وst. معرفة هذه الأصوات تساعدك على فهم الآخرين وعلى أن يفهموك في الإنجليزية اليومية. وبعد الدرس ستستطيع التمييز بينها ونطق الكلمات نطقًا صحيحًا.","sections":[{"heading":"صوتا p وb","body":"- صوت p نفخة هواء خفيفة بلا جهر.\n- صوت b يستخدم الصوت، كأنه طنين قصير.\n- أصغِ إلى النفَس في p وإلى الطنين في b.","examples":[{"text":"pat vs bat","note":"يوضح النفخة (p) والطنين (b) في بداية الكلمة"},{"text":"pop vs bob","note":"النمط نفسه في وسط الكلمة"},{"text":"cap vs cab","note":"الصوت الأخير يتغير من p إلى b"}]},{"heading":"صوتا f وv","body":"- صوت f يخرج بلا جهر، هواء فقط.\n- صوت v يضيف الجهر، أي اهتزازًا خفيفًا.\n- المس حنجرتك: لا طنين مع f، وطنين مع v.","examples":[{"text":"fan vs van","note":"الصوت الأول: f هادئ وv مجهور"},{"text":"fine vs vine","note":"يوضح الفرق في وسط الكلمة"},{"text":"leaf vs leave","note":"تنتهي الكلمة بـ f (هادئ) أو v (طنين)"}]},{"heading":"المقاطع المركّبة الشائعة: bl وst","body":"- المقطع المركّب يعني نطق صوتين ساكنين معًا بسرعة.\n- يُنطق bl كأنه “b” ثم “l” في حركة واحدة سلسة.\n- يُنطق st كأنه “s” ثم “t” دون حركة بينهما.\n- تدرّب على نطق الزوج كقطعة واحدة.","examples":[{"text":"blue","note":"مقطع bl في بداية الكلمة"},{"text":"black","note":"مقطع bl متبوعًا بحرف علة"},{"text":"stop","note":"مقطع st في بداية الكلمة"},{"text":"star","note":"مقطع st متبوعًا بحرف علة"}]},{"heading":"جمل تدريب بسيطة","body":"- استخدم الأصوات التي تعلمتها في جمل قصيرة.\n- انطق كل جملة ببطء وأحسّ بالنفَس أو الطنين.\n- حاول تقليد إيقاع المتحدث الأصلي.","examples":[{"text":"Bob has a blue ball.","note":"تحتوي على أصوات b وbl وb"},{"text":"Pat can fix the fan.","note":"تحتوي على أصوات p وf وst"},{"text":"Van and Van are very fast.","note":"تحتوي على أصوات v ومقاطع st"}]}],"keyPoints":["صوت p نفخة هواء، وصوت b يضيف الجهر بالصوت","صوت f هادئ، وصوت v يهزّ الحنجرة","يُنطق bl وst معًا دون حركة إضافية بينهما","أصغِ إلى النفَس في p وf وإلى الاهتزاز في b وv","تدرّب ببطء أولًا ثم زد السرعة"],"commonMistakes":[{"wrong":"Bob says “bop” for “pop”","right":"Bob says “pop”","why":"كثيرًا ما يستبدل المتحدثون بالعربية صوت p بصوت b"},{"wrong":"She says “vane” as “fan”","right":"She says “van”","why":"صوت v غير موجود في العربية"},{"wrong":"She says “buh‑lue” for “blue”","right":"She says “blue”","why":"إضافة حركة بين حرفي المقطع المركّب تفكك المقطع"},{"wrong":"He says “st‑ar” with a pause","right":"He says “star” smoothly","why":"التوقف يضيف صوتًا زائدًا لا ينبغي وجوده"}],"recap":"استمع إلى التسجيل، وكرّر كل كلمة، ثم جرّب جمل التدريب بصوتٍ عالٍ."},"assets":{"3a369d60-4b88-4210-a51d-eb7b20c3e9d5":{"title":"استمع: Pat مقابل Bat، وFan مقابل Van","description":"استمع إلى أزواج الكلمات ولاحظ الفرق بين الصوتين."}}}$aimseed$::jsonb)
