-- lesson c22f5f45-e427-4cc4-bc40-270ce97f27c1: Numbers 0-10
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('c22f5f45-e427-4cc4-bc40-270ce97f27c1', 'ar', $aimseed$الأرقام من 0 إلى 10$aimseed$, $aimseed$تعلّم نطق الأرقام من 0 إلى 10 والتعرّف عليها.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستتعلم كيف تنطق الأرقام من صفر إلى عشرة وتتعرّف عليها. معرفة هذه الأرقام تتيح لك أن تتحدث عن الكميات في المواقف اليومية. وبعد الدرس ستستطيع العدّ وقراءة الأرقام واستخدام الأرقام من 0 إلى 10.","sections":[{"heading":"انطق الأرقام","body":"- zero\n- one\n- two\n- three\n- four\n- five\n- six\n- seven\n- eight\n- nine\n- ten","examples":[{"text":"I have three apples.","note":"يوضح كيف تعبّر عن كمية"},{"text":"She is five years old.","note":"يوضح استخدام الرقم للتعبير عن العمر"},{"text":"There are seven chairs.","note":"يوضح عدّ الأشياء"}]},{"heading":"اقرأ الأرقام","body":"- 0 = zero\n- 1 = one\n- 2 = two\n- 3 = three\n- 4 = four\n- 5 = five\n- 6 = six\n- 7 = seven\n- 8 = eight\n- 9 = nine\n- 10 = ten","examples":[{"text":"Room 4 is on the left.","note":"التعرّف على الرقم 4"},{"text":"My phone number starts with 0.","note":"التعرّف على الرقم 0"},{"text":"The price is 9 dollars.","note":"قراءة الرقم 9"}]},{"heading":"استخدم الأرقام في جمل بسيطة","body":"- How many? – Two.\n- I need five tickets.\n- There are ten students.","examples":[{"text":"How many cats do you have? – Two.","note":"سؤال وجواب بالرقم"},{"text":"I need five tickets.","note":"استخدام الرقم لطلب شيء"},{"text":"There are ten students in the class.","note":"ذكر المجموع الكلي"}]}],"keyPoints":["الأرقام من صفر إلى عشرة هي أول الأرقام التي تحتاج إلى معرفتها.","انطق كل رقم بوضوح: zero, one, two, three, four, five, six, seven, eight, nine, ten.","الرقم المكتوب يطابق الكلمة المنطوقة (0 = zero، 1 = one، وهكذا).","استخدم الأرقام بعد أفعال مثل have وneed وare.","أجب عن الأسئلة البسيطة بكلمة الرقم فقط."],"commonMistakes":[{"wrong":"I have three apple.","right":"I have three apples.","why":"الاسم الجمع يحتاج إلى -s بعد الرقم"},{"wrong":"She is five year old.","right":"She is five years old.","why":"استخدم الجمع 'years' بعد الرقم"},{"wrong":"Room 4 is left.","right":"Room 4 is on the left.","why":"أضف حرف الجر 'on' للتعبير عن المكان"},{"wrong":"How many cats you have? – Two.","right":"How many cats do you have? – Two.","why":"أضف الفعل المساعد 'do' في السؤال"}],"recap":"تدرّب على العدّ بصوتٍ عالٍ، وعلى قراءة الأرقام، وعلى تكوين جمل بسيطة بالأرقام من 0 إلى 10."},"assets":{"04d19f8c-0549-41eb-8e3c-2351d56dcd71":{"title":"الأرقام من 0 إلى 10","description":"zero, one, two, three, four, five, six, seven, eight, nine, ten"}}}$aimseed$::jsonb)
