-- lesson ec07a074-825b-4d4d-91b6-c612b7a58df6: Counting Practice
INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('ec07a074-825b-4d4d-91b6-c612b7a58df6', 'ar', $aimseed$تدريب على العدّ$aimseed$, $aimseed$استمع إلى الأرقام المنطوقة وتدرّب على التعرّف عليها بالأذن.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستسمع الأرقام من صفر إلى عشرين. وستتعلم كيف تعرف أي رقم سمعته. وبعد التدريب ستستطيع التعرّف على أي رقم منطوق بين 0 و20.","sections":[{"heading":"استمع إلى كل رقم","body":"- اضغط تشغيل واستمع جيدًا.\n- عُدّ النبرات التي تسمعها.\n- لاحظ شكل كل كلمة.","examples":[{"text":"zero","note":"أول رقم ستسمعه"},{"text":"seven","note":"رقم من الوسط بصوت قصير"},{"text":"fifteen","note":"كلمة من مقطعين تُسمع كعبارة واحدة سلسة"}]},{"heading":"طابق الصوت بالرقم","body":"- بعد أن تسمع رقمًا، انظر إلى قائمة الأرقام من 0 إلى 20.\n- اختر الرقم الذي يطابق الصوت.\n- تأكد من صحة الرقم الذي اخترته.","examples":[{"text":"You hear \"four\" → write 4","note":"يربط الكلمة المنطوقة بالرقم المكتوب"},{"text":"You hear \"eleven\" → write 11","note":"يوضح رقمًا من خانتين"},{"text":"You hear \"nine\" → write 9","note":"مطابقة بسيطة لرقم من خانة واحدة"}]},{"heading":"انطق الأرقام بنفسك","body":"- انظر إلى رقم على الشاشة.\n- انطق الكلمة الإنجليزية بصوتٍ عالٍ.\n- قارن نطقك بالتسجيل الصوتي.","examples":[{"text":"12 → say \"twelve\"","note":"تدرّب على نطق رقم من أرقام الـ teen"},{"text":"3 → say \"three\"","note":"تدرّب على صوت ساكن قصير"},{"text":"20 → say \"twenty\"","note":"تدرّب على نطق النهاية \"ty\""}]}],"keyPoints":["صفر هو أول رقم، ويُنطق \"zero\".","الأرقام من 1 إلى 9 كلمات مفردة، أما من 10 إلى 20 فهي ten وeleven وtwelve … twenty.","أصغِ إلى الصوت الأول لتعرف هل الرقم من خانة واحدة أم من أرقام الـ teen.","تدرّب على نطق كل رقم لتسمع الفرق بينها."],"commonMistakes":[{"wrong":"Heard \"nine\" and wrote 19","right":"Heard \"nine\" and wrote 9","why":"صوتا nine وnineteen متشابهان"},{"wrong":"Forgot to listen for zero","right":"Include zero when counting","why":"الصفر جزء من النطاق 0‑20"},{"wrong":"Matched the spelling instead of the sound","right":"Match the spoken sound to the digit","why":"كثيرًا ما يعتمد المتحدثون بالعربية على الحروف لا على النطق"},{"wrong":"Counted too fast and missed the number","right":"Pause after each number and count slowly","why":"الاستماع البطيء يرفع الدقة"}],"recap":"استمع، وطابق، وانطق كل رقم من 0 إلى 20؛ وكرّر حتى تتعرّف عليها فورًا."},"assets":{"e045c0a9-ba7b-4213-bf1c-5122805224cf":{"title":"استمع: العدّ من 0 إلى 20","description":"استمع وعُدّ معنا."}}}$aimseed$::jsonb)
ON CONFLICT (lesson_id, locale) DO UPDATE SET content = EXCLUDED.content;
