INSERT INTO lesson_translations (lesson_id, locale, title, description, content)
VALUES ('ff15074f-616f-47bb-a68d-b3ee55a873d2', 'ar', $aimseed$كلمات العائلة$aimseed$, $aimseed$تعلّم مفردات أفراد العائلة الأساسية: mother, father, sister, brother.$aimseed$, $aimseed${"explanation":{"overview":"في هذا الدرس ستتعلّم أكثر أربع كلمات شيوعًا عن العائلة: mother وfather وsister وbrother. معرفة هذه الكلمات تتيح لك الحديث عن الأشخاص الذين تعيش معهم. بعد الدرس ستتمكّن من تسمية كل فرد من العائلة بشكل صحيح في جمل قصيرة.","sections":[{"heading":"قائمة كلمات العائلة","body":"- mother: الوالدة (الأم)\n- father: الوالد (الأب)\n- sister: الأخت\n- brother: الأخ","examples":[{"text":"This is my mother.","note":"توضّح كيف تشير إلى الأم"},{"text":"My father is tall.","note":"توضّح father فاعلًا في الجملة"},{"text":"She is my sister.","note":"استخدام sister مع ضمير"},{"text":"He is my brother.","note":"استخدام brother مع ضمير"}]},{"heading":"جمل بسيطة بكلمات العائلة","body":"- My mother works. (أمي تعمل.)\n- My father reads. (أبي يقرأ.)\n- My sister sings. (أختي تغنّي.)\n- My brother plays. (أخي يلعب.)","examples":[{"text":"My mother works.","note":"الفاعل + الفعل + mother"},{"text":"My father reads.","note":"الفاعل + الفعل + father"},{"text":"My sister sings.","note":"الفاعل + الفعل + sister"},{"text":"My brother plays.","note":"الفاعل + الفعل + brother"}]},{"heading":"تحدّث عن عائلتك","body":"- I have a mother and a father. (لدي أم وأب.)\n- I have one sister. (لدي أخت واحدة.)\n- I have two brothers. (لدي أخوان.)\n- My family is small. (عائلتي صغيرة.)","examples":[{"text":"I have a mother and a father.","note":"توضّح الملكية باستخدام 'have'"},{"text":"I have one sister.","note":"عدّ الأخوات"},{"text":"I have two brothers.","note":"عدّ الإخوة"},{"text":"My family is small.","note":"استخدام كلمة عائلة في الوصف"}]},{"heading":"الإجابة عن أسئلة بسيطة","body":"- Who is this? – She is my sister. (من هذه؟ هي أختي.)\n- Who is he? – He is my brother. (من هو؟ هو أخي.)\n- Who is your mother? – She is my mother. (من أمك؟ هي أمي.)\n- Who is your father? – He is my father. (من أبوك؟ هو أبي.)","examples":[{"text":"Who is this? She is my sister.","note":"نمط السؤال والجواب"},{"text":"Who is he? He is my brother.","note":"نمط السؤال والجواب"},{"text":"Who is your mother? She is my mother.","note":"استخدام 'your' و'my' بشكل صحيح"},{"text":"Who is your father? He is my father.","note":"استخدام 'your' و'my' بشكل صحيح"}]}],"keyPoints":["كلمات العائلة أسماء تدل على الأشخاص الذين تربطك بهم صلة قرابة","استخدم 'my' قبل الكلمة لتدل على أن الشخص لك","الفعل 'to be' (am/is/are) يُستخدم كثيرًا مع كلمات العائلة","عندما تشير إلى شخص يمكنك قول 'This is my …'","لا نحتاج في هذا الدرس المبتدئ إلى صيغ الجمع (mothers, fathers)"],"commonMistakes":[{"wrong":"She is mother.","right":"She is my mother.","why":"تحتاج إلى كلمة مثل 'my' لتدل على الملكية"},{"wrong":"I am father.","right":"My father is tall.","why":"استخدم 'my' قبل كلمة العائلة، وليس 'I am'"},{"wrong":"I have mother.","right":"I have a mother.","why":"أضف أداة التنكير 'a' عند الحديث عن فرد واحد من العائلة"},{"wrong":"Who is you?","right":"Who is your mother?","why":"استخدم صيغة الملكية 'your' عند السؤال عن عائلة شخص آخر"}],"recap":"تدرّب على تسمية كل فرد من العائلة باستخدام 'my' والإجابة عن أسئلة بسيطة عنهم."},"assets":{"ac5fa2fe-da9c-45b1-9528-cec646a57340":{"title":"كلمات العائلة","description":"mother (أم), father (أب), sister (أخت), brother (أخ), family (عائلة). This is my mother. (هذه أمي.)"}}}$aimseed$::jsonb)
